window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-04fcfd0e3742df4a"]={"versions": [{"id": "FIG-04fcfd0e3742df4a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Software-Komponenten-Vorlage (<code>AUTOSAR_SoftwareComponentTemplate</code>), spezifisch für das Typ-Prototyp-Muster bei Datentypen und Datenprototypen. Das Diagramm modelliert die strukturellen Beziehungen zwischen Typdefinitionen (<code>Datatype</code>), Prototyp-Abstraktionen (<code>DataPrototype</code>) sowie deren konkreten Spezialisierungen im Kontext von Software-Komponenten und Datenbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>Datatype</code>: Abstrakt (<code>ARElement</code>, Stereotyp <code>«atpType»</code>), fungiert als Typdefinition im Metamodell.\n</li><li><code>DataPrototype</code>: Abstrakte Metaklasse (<code>Identifiable</code>, Stereotyp <code>«atpPrototype»</code>), repräsentiert Dateninstanzierungen basierend auf Datentypen.\n</li><li>Assoziation <code>«isOfType»</code>: Gerichtete Assoziation von <code>DataPrototype</code> (Kardinalität <code>0..*</code>) zu <code>Datatype</code> (Rollenname <code>+type</code>, Kardinalität <code>1</code>).\n</li><li>Komposition zu <code>SwDataDefProps</code>: <code>DataPrototype</code> aggregiert über eine Komposition mit Rollennamen <code>+swDataDefProps</code> optional (<code>0..1</code>) softwarebezogene Datendefinitionseigenschaften (<code>SwDataDefProps</code>, markiert als <code>IsSyscond</code>).\n</li><li>Spezialisierungen von <code>DataPrototype</code> (Generalisierungsbeziehung):\n<ul class=\"fig-list\"><li><code>RecordElement</code>\n</li><li><code>ValueSpecification</code>\n</li><li><code>DataElementPrototype</code>\n</li><li><code>ArgumentPrototype</code>\n</li><li><code>CalprmElementPrototype</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Ablaufsemantik. Das Diagramm definiert deklarative Typisierungs- und Vererbungsstrukturen zur Entwurfszeit für die Instanziierung von Datenprototypen und deren Zuordnung zu AUTOSAR-Datentypen sowie systemspezifischen Eigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Definition für Modellierungswerkzeuge und Generatoren in der AUTOSAR Classic Platform. Jeder von <code>DataPrototype</code> abgeleitete Datenprototyp muss genau einem <code>Datatype</code> über die Assoziation <code>+type</code> zugeordnet sein (<code>1</code>). Die Konfigurationseigenschaften über <code>+swDataDefProps</code> sind optional (<code>0..1</code>) und systemspezifisch konditionierbar (<code>IsSyscond</code>). Model-Transformationen müssen sämtliche Spezialisierungen (<code>RecordElement</code>, <code>ValueSpecification</code>, <code>DataElementPrototype</code>, <code>ArgumentPrototype</code>, <code>CalprmElementPrototype</code>) typkonform auflösen.</p>"}, {"id": "FIG-021dc0f0d6d18a40", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Software-Komponenten-Vorlage (<code>AUTOSAR_SoftwareComponentTemplate</code>), spezifisch für das Typ-Prototyp-Muster bei Datentypen und Datenprototypen. Das Diagramm modelliert die strukturellen Beziehungen zwischen Typdefinitionen (<code>Datatype</code>), Prototyp-Abstraktionen (<code>DataPrototype</code>) sowie deren konkreten Spezialisierungen im Kontext von Software-Komponenten und Datenbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>Datatype</code>: Abstrakt (<code>ARElement</code>, Stereotyp <code>«atpType»</code>), fungiert als Typdefinition im Metamodell.\n</li><li><code>DataPrototype</code>: Abstrakte Metaklasse (<code>Identifiable</code>, Stereotyp <code>«atpPrototype»</code>), repräsentiert Dateninstanzierungen basierend auf Datentypen.\n</li><li>Assoziation <code>«isOfType»</code>: Gerichtete Assoziation von <code>DataPrototype</code> (Kardinalität <code>0..*</code>) zu <code>Datatype</code> (Rollenname <code>+type</code>, Kardinalität <code>1</code>).\n</li><li>Komposition zu <code>SwDataDefProps</code>: <code>DataPrototype</code> aggregiert über eine Komposition mit Rollennamen <code>+swDataDefProps</code> optional (<code>0..1</code>) softwarebezogene Datendefinitionseigenschaften (<code>SwDataDefProps</code>, markiert als <code>IsSyscond</code>).\n</li><li>Spezialisierungen von <code>DataPrototype</code> (Generalisierungsbeziehung):\n<ul class=\"fig-list\"><li><code>RecordElement</code>\n</li><li><code>ValueSpecification</code>\n</li><li><code>DataElementPrototype</code> (Stereotyp <code>«atpPrototype»</code>)\n</li><li><code>ArgumentPrototype</code>\n</li><li><code>CalprmElementPrototype</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Ablaufsemantik. Das Diagramm definiert deklarative Typisierungs- und Vererbungsstrukturen zur Entwurfszeit für die Instanziierung von Datenprototypen und deren Zuordnung zu AUTOSAR-Datentypen sowie systemspezifischen Eigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Definition für Modellierungswerkzeuge und Generatoren in der AUTOSAR Classic Platform. Jeder von <code>DataPrototype</code> abgeleitete Datenprototyp muss genau einem <code>Datatype</code> über die Assoziation <code>+type</code> zugeordnet sein (<code>1</code>). Die Konfigurationseigenschaften über <code>+swDataDefProps</code> sind optional (<code>0..1</code>) und systemspezifisch konditionierbar (<code>IsSyscond</code>). Model-Transformationen müssen sämtliche Spezialisierungen (<code>RecordElement</code>, <code>ValueSpecification</code>, <code>DataElementPrototype</code>, <code>ArgumentPrototype</code>, <code>CalprmElementPrototype</code>) typkonform auflösen.</p>"}, {"id": "FIG-51600772ccd93ffb", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Software-Komponenten-Vorlage (<code>AUTOSAR_SoftwareComponentTemplate</code>), spezifisch für das Typ-Prototyp-Muster bei Datentypen und Datenprototypen. Das Diagramm modelliert die strukturellen Beziehungen zwischen Typdefinitionen (<code>Datatype</code>), Prototyp-Abstraktionen (<code>DataPrototype</code>) sowie deren konkreten Spezialisierungen im Kontext von Software-Komponenten und Datenbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>Datatype</code>: Abstrakt (<code>ARElement</code>, Stereotyp <code>«atpType»</code>), fungiert als Typdefinition im Metamodell.\n</li><li><code>DataPrototype</code>: Abstrakte Metaklasse (<code>Identifiable</code>, Stereotyp <code>«atpPrototype»</code>), repräsentiert Dateninstanzierungen basierend auf Datentypen.\n</li><li>Assoziation <code>«isOfType»</code>: Gerichtete Assoziation von <code>DataPrototype</code> (Kardinalität <code>0..*</code>) zu <code>Datatype</code> (Rollenname <code>+type</code>, Kardinalität <code>1</code>).\n</li><li>Komposition zu <code>SwDataDefProps</code>: <code>DataPrototype</code> aggregiert über eine Komposition mit Rollennamen <code>+swDataDefProps</code> optional (<code>0..1</code>) softwarebezogene Datendefinitionseigenschaften (<code>SwDataDefProps</code>, markiert als <code>IsSyscond</code>).\n</li><li>Spezialisierungen von <code>DataPrototype</code> (Generalisierungsbeziehung):\n<ul class=\"fig-list\"><li><code>RecordElement</code>\n</li><li><code>ValueSpecification</code>\n</li><li><code>DataElementPrototype</code> (Stereotyp <code>«atpPrototype»</code>)\n</li><li><code>ArgumentPrototype</code>\n</li><li><code>CalprmElementPrototype</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Ablaufsemantik. Das Diagramm definiert deklarative Typisierungs- und Vererbungsstrukturen zur Entwurfszeit für die Instanziierung von Datenprototypen und deren Zuordnung zu AUTOSAR-Datentypen sowie systemspezifischen Eigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Definition für Modellierungswerkzeuge und Generatoren in der AUTOSAR Classic Platform. Jeder von <code>DataPrototype</code> abgeleitete Datenprototyp muss genau einem <code>Datatype</code> über die Assoziation <code>+type</code> zugeordnet sein (<code>1</code>). Die Konfigurationseigenschaften über <code>+swDataDefProps</code> sind optional (<code>0..1</code>) und systemspezifisch konditionierbar (<code>IsSyscond</code>). Model-Transformationen müssen sämtliche Spezialisierungen (<code>RecordElement</code>, <code>ValueSpecification</code>, <code>DataElementPrototype</code>, <code>ArgumentPrototype</code>, <code>CalprmElementPrototype</code>) typkonform auflösen.</p>"}, {"id": "FIG-6642e609e394530d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Software-Komponenten-Vorlage (<code>AUTOSAR_SoftwareComponentTemplate</code>), spezifisch für das Typ-Prototyp-Muster bei Datentypen und Datenprototypen. Das Diagramm modelliert die strukturellen Beziehungen zwischen Typdefinitionen (<code>Datatype</code>), Prototyp-Abstraktionen (<code>DataPrototype</code>) sowie deren konkreten Spezialisierungen im Kontext von Software-Komponenten und Datenbeschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Metaklassen und Relationen:</p>\n<ul class=\"fig-list\"><li><code>Datatype</code>: Abstrakt (<code>ARElement</code>, Stereotyp <code>«atpType»</code>), fungiert als Typdefinition im Metamodell.\n</li><li><code>DataPrototype</code>: Abstrakte Metaklasse (<code>Identifiable</code>, Stereotyp <code>«atpPrototype»</code>), repräsentiert Dateninstanzierungen basierend auf Datentypen.\n</li><li>Assoziation <code>«isOfType»</code>: Gerichtete Assoziation von <code>DataPrototype</code> (Kardinalität <code>0..*</code>) zu <code>Datatype</code> (Rollenname <code>+type</code>, Kardinalität <code>1</code>).\n</li><li>Komposition zu <code>SwDataDefProps</code>: <code>DataPrototype</code> aggregiert über eine Komposition mit Rollennamen <code>+swDataDefProps</code> optional (<code>0..1</code>) softwarebezogene Datendefinitionseigenschaften (<code>SwDataDefProps</code>, markiert als <code>IsSyscond</code>).\n</li><li>Spezialisierungen von <code>DataPrototype</code> (Generalisierungsbeziehung):\n<ul class=\"fig-list\"><li><code>RecordElement</code>\n</li><li><code>ValueSpecification</code>\n</li><li><code>DataElementPrototype</code> (Stereotyp <code>«atpPrototype»</code>)\n</li><li><code>NvBlockDataPrototype</code> (Stereotyp <code>«atpPrototype»</code>)\n</li><li><code>ArgumentPrototype</code>\n</li><li><code>CalprmElementPrototype</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Ablaufsemantik. Das Diagramm definiert deklarative Typisierungs- und Vererbungsstrukturen zur Entwurfszeit für die Instanziierung von Datenprototypen und deren Zuordnung zu AUTOSAR-Datentypen sowie systemspezifischen Eigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Definition für Modellierungswerkzeuge und Generatoren in der AUTOSAR Classic Platform. Jeder von <code>DataPrototype</code> abgeleitete Datenprototyp (einschließlich <code>NvBlockDataPrototype</code>) muss genau einem <code>Datatype</code> über die Assoziation <code>+type</code> zugeordnet sein (<code>1</code>). Die Konfigurationseigenschaften über <code>+swDataDefProps</code> sind optional (<code>0..1</code>) und systemspezifisch konditionierbar (<code>IsSyscond</code>). Model-Transformationen und Generatoren für nichtflüchtige Speicherblöcke und Softwarekomponenten müssen sämtliche Spezialisierungen (<code>RecordElement</code>, <code>ValueSpecification</code>, <code>DataElementPrototype</code>, <code>NvBlockDataPrototype</code>, <code>ArgumentPrototype</code>, <code>CalprmElementPrototype</code>) typkonform behandeln.</p>"}], "trans": [{"from": "FIG-04fcfd0e3742df4a", "to": "FIG-021dc0f0d6d18a40", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>DataElementPrototype</code>: Stereotyp <code>«atpPrototype»</code> ergänzt.\n</li></ul>"}, {"from": "FIG-021dc0f0d6d18a40", "to": "FIG-51600772ccd93ffb", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-51600772ccd93ffb", "to": "FIG-6642e609e394530d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>NvBlockDataPrototype</code>: Neue Spezialisierungsklasse von <code>DataPrototype</code> mit Stereotyp <code>«atpPrototype»</code> ergänzt.\n</li><li>Diagrammlayout: Spezialisierungen von <code>DataPrototype</code> zweizeilig angeordnet.\n</li></ul>"}]};
